SELECT b.id, b.title, b.author, b.price, b.cover_image_url, b.difficulty_tag, bs.sales, bs.avg_rating, bs.review_count, bs.favorite_count, (SELECT GROUP_CONCAT(t.name SEPARATOR ',') FROM book_tag_relation r INNER JOIN book_tag t ON r.tag_id = t.id WHERE r.book_id = b.id ) AS tag_names_str FROM book_info b LEFT JOIN book_stats bs ON b.id = bs.book_id
b.is_deleted = 0
AND b.category_id = #{categoryId}
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR b.author LIKE CONCAT('%', #{keyword}, '%') OR b.description LIKE CONCAT('%', #{keyword}, '%') OR b.region LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY bs.sales ${sortOrder}
ORDER BY bs.favorite_count ${sortOrder}
ORDER BY bs.avg_rating ${sortOrder}
ORDER BY b.price ${sortOrder}
ORDER BY b.publish_date ${sortOrder}
ORDER BY b.id DESC
ORDER BY b.id DESC

SELECT
b.id, b.title, b.author, b.price, b.cover_image_url,
b.difficulty_tag,
bs.sales, bs.avg_rating, bs.review_count, bs.favorite_count,
(
SELECT GROUP_CONCAT(t.name SEPARATOR ',')
FROM book_tag_relation r
INNER JOIN book_tag t ON r.tag_id = t.id
WHERE r.book_id = b.id
) AS tag_names_str
FROM book_info b
LEFT JOIN book_stats bs ON b.id = bs.book_id

    b.status = 1 AND b.is_deleted = 0

        AND b.category_id = #{query.categoryId}


        AND b.title LIKE CONCAT('%', #{query.title}, '%')


        AND b.author LIKE CONCAT('%', #{query.author}, '%')


        AND YEAR(b.publish_date) >= #{query.minYear}


        AND YEAR(b.publish_date) <= #{query.maxYear}


        AND b.difficulty_tag = #{query.difficultyTag}


        AND b.region LIKE CONCAT('%', #{query.region}, '%')


        AND b.price >= #{query.minPrice}


        AND b.price <= #{query.maxPrice}






                ORDER BY bs.sales ${query.sortOrder}


                ORDER BY bs.favorite_count ${query.sortOrder}


                ORDER BY bs.avg_rating ${query.sortOrder}


                ORDER BY b.price ${query.sortOrder}


                ORDER BY b.publish_date ${query.sortOrder}




        ORDER BY b.id DESC
